            ["startup.failedTitle"] = ("TeleSelfCloud startup error", "Lỗi khởi động TeleSelfCloud"),
            ["startup.failed"] = ("TeleSelfCloud could not start. Keep the local profile, check free space and file access, and close other instances before retrying. If the error persists, restore a verified profile backup or provide this diagnostic code.\n\nCode: {0}\nReport: {1}\n\nSensitive error details were omitted.", "Không khởi động được TeleSelfCloud. Giữ hồ sơ local, kiểm tra dung lượng và quyền truy cập tệp, đóng các instance khác rồi thử lại. Nếu lỗi còn xảy ra, phục hồi backup hồ sơ đã xác minh hoặc cung cấp mã chẩn đoán này.\n\nMã: {0}\nBáo cáo: {1}\n\nĐã bỏ chi tiết lỗi nhạy cảm."),
            ["metadata.crypto.title"] = ("Vault metadata encryption", "Mã hóa metadata của kho"),
            ["metadata.crypto.scopeChanged"] = ("The vault or its key changed while this action was pending. Its key was not installed. Reopen the intended vault's Settings and try again.", "Kho hoặc khóa đã đổi khi thao tác đang chờ. Không cài đặt khóa. Mở lại Cài đặt của đúng kho rồi thử lại."),
            ["metadata.crypto.backupOnly"] = ("The recovery backup was saved for the original vault, but its active context changed. No key was installed. Keep that backup and reopen the intended vault's Settings.", "Đã lưu backup phục hồi cho kho ban đầu nhưng context đang dùng đã đổi. Không cài đặt khóa. Giữ backup đó và mở lại Cài đặt của đúng kho."),
            ["metadata.crypto.backupOutsideProfile"] = ("Save the recovery backup outside the application's profile so it cannot overwrite live data.", "Lưu backup khóa phục hồi ngoài hồ sơ ứng dụng để không ghi đè dữ liệu đang dùng."),
            ["metadata.crypto.invalidRecovery"] = ("Wrong recovery passphrase or damaged metadata key. Protected files were kept; use the correct recovery backup.", "Sai passphrase phục hồi hoặc khóa metadata bị hỏng. Giữ các tệp được bảo vệ; hãy dùng đúng backup khóa."),
            ["metadata.crypto.enable"] = ("Enable and save recovery key", "Bật và lưu khóa phục hồi"),
            ["metadata.crypto.export"] = ("Export recovery key", "Xuất khóa phục hồi"),
            ["metadata.crypto.recover"] = ("Recover metadata key", "Phục hồi khóa metadata"),
            ["metadata.crypto.off"] = ("Remote metadata encryption is off for this vault.", "Chưa bật mã hóa metadata remote cho kho này."),
            ["metadata.crypto.enabled"] = ("New and revised manifests/folder snapshots are encrypted. Earlier remote history remains readable. Local catalog protection is configured separately.", "Manifest và snapshot thư mục mới/được sửa sẽ mã hóa. Lịch sử remote cũ vẫn đọc được. Bảo vệ catalog local được cài đặt riêng."),
            ["metadata.crypto.keyUnavailable"] = ("This vault's metadata key could not be opened. Recover its key before publishing; protected files were kept.", "Không mở được khóa metadata của kho. Phục hồi khóa trước khi gửi; giữ các tệp được bảo vệ."),
            ["metadata.crypto.passphrase"] = ("Enter a recovery passphrase of at least 12 characters.", "Nhập passphrase phục hồi ít nhất 12 ký tự."),
            ["metadata.crypto.helper"] = ("Save the recovery key outside this device. It is required on a new device. This protects future remote metadata; existing history is unchanged. Configure local catalog protection separately.", "Lưu khóa phục hồi bên ngoài thiết bị này để dùng trên máy mới. Mã hóa áp dụng cho metadata remote về sau; lịch sử cũ không đổi. Cài đặt bảo vệ catalog local riêng."),
            ["metadata.crypto.working"] = ("Protecting and verifying the metadata key...", "Đang bảo vệ và xác minh khóa metadata..."),
            ["metadata.crypto.saved"] = ("Metadata key saved and verified. Keep its recovery file and passphrase safely; sync to read encrypted remote documents.", "Đã lưu và xác minh khóa metadata. Giữ tệp phục hồi và passphrase an toàn; đồng bộ để đọc tài liệu remote mã hóa."),
            ["files.view.details"] = ("Details", "Chi tiết"),
            ["files.view.icons"] = ("Icons", "Biểu tượng"),
            ["files.view.detailsTip"] = ("Show files in Details view", "Hiển thị tệp dạng Chi tiết"),
            ["files.view.iconsTip"] = ("Show files in Icons grid view", "Hiển thị tệp dạng Biểu tượng/lưới"),
            ["vault.noChoices"] = ("No vault available", "Chưa có kho khả dụng"),
            ["upload.closeSelection"] = ("Close", "Đóng"),
            ["upload.closeSelectionTip"] = ("Close upload options and clear the selected source files. Uploaded files and queued transfers are kept. While a transfer is running, use its Cancel or Pause control first.", "Đóng phần tải lên và bỏ lựa chọn tệp nguồn. Tệp đã tải lên và tác vụ đã vào hàng đợi được giữ nguyên. Khi đang truyền, hãy dùng nút Hủy hoặc Tạm dừng của tác vụ trước."),
            ["storage.connection.progress"] = ("Connecting private storage. Please wait…", "Đang kết nối kho riêng tư. Vui lòng chờ…"),
            ["storage.connection.busy"] = ("Wait for the current operation to finish, then connect again.", "Hãy chờ thao tác hiện tại kết thúc rồi kết nối lại."),
            ["storage.connection.signIn"] = ("Complete Telegram sign-in before connecting storage.", "Hãy hoàn tất đăng nhập Telegram trước khi kết nối kho."),
            ["storage.connection.profileLoading"] = ("The account profile is still opening. Please wait, then connect again.", "Đang mở hồ sơ tài khoản. Vui lòng chờ rồi kết nối lại."),
            ["vault.profileUnavailable"] = ("Vault options are unavailable because the account profile could not be opened. Existing data was kept. Review the detailed error below and the profile backup before retrying sign-in.", "Chưa thể dùng các tùy chọn kho vì hồ sơ tài khoản không mở được. Dữ liệu hiện có được giữ nguyên. Xem lỗi chi tiết bên dưới và kiểm tra bản sao lưu hồ sơ trước khi đăng nhập lại."),
            ["vault.empty.help"] = ("No vault choices are loaded. Use Add existing or Find vaults after connecting your account.", "Chưa có lựa chọn kho. Dùng Thêm kho có sẵn hoặc Tìm kho sau khi kết nối tài khoản."),
            ["vault.empty.loading"] = ("Connecting storage. Vault choices will appear after verification.", "Đang kết nối kho. Lựa chọn sẽ xuất hiện sau khi xác minh."),
            ["vault.empty.catalogError"] = ("The local catalog could not be attached safely. It has been retained. Use Recover in a separate vault; see the error below for details.", "Không thể gắn catalog local an toàn. Catalog được giữ nguyên. Chọn Phục hồi vào kho riêng; xem lỗi bên dưới để biết chi tiết."),
            ["vault.choice.active"] = ("Current vault", "Kho đang dùng"),
            ["vault.choice.registered"] = ("Registered vault", "Kho đã đăng ký"),
            ["vault.choice.discovered"] = ("Discovered · verify when opening", "Đã tìm thấy · xác minh khi mở"),
            ["vault.choice.help"] = ("Choose a vault, then select Open vault. Use arrow keys to choose and Escape to close.", "Chọn kho rồi nhấn Mở kho. Dùng phím mũi tên để chọn, Escape để đóng."),
            ["vault.heading"] = ("Vault", "Kho"),
            ["vault.abandon"] = ("Stop recovery", "Dừng phục hồi"),
            ["vault.abandonConfirm"] = ("Stop recovering this creation attempt? Its journal will be archived locally. Telegram may already have created the channel; this does not remove or undo it. Find vaults and check Telegram before creating another, which could leave duplicate channels.", "Dừng phục hồi lượt tạo này? Journal sẽ được lưu trữ local. Telegram có thể đã tạo kênh; thao tác này không xóa hay hoàn tác kênh. Hãy tìm kho và kiểm tra Telegram trước khi tạo kho khác vì có thể để lại kênh trùng."),
            ["vault.abandoned"] = ("Creation recovery stopped; the journal was archived. Remote channels were kept. Find vaults before creating another.", "Đã dừng phục hồi lượt tạo và lưu trữ journal. Giữ các kênh remote. Hãy tìm kho trước khi tạo kho khác."),
            ["vault.discover"] = ("Find vaults", "Tìm kho"),
            ["vault.recoverCreation"] = ("Recover creation", "Phục hồi tạo kho"),
            ["vault.discovered"] = ("Found {0} verified vaults. Choose one and open it. The current vault and local records were kept.", "Tìm thấy {0} kho đã xác minh. Chọn kho rồi mở. Giữ kho đang mở và dữ liệu local."),
            ["vault.verificationRecovery"] = ("Telegram created storage chat {0}, but verification did not finish. Add this existing chat instead of creating another. {1}", "Telegram đã tạo chat lưu trữ {0} nhưng chưa xác minh xong. Thêm kho có sẵn với ID này thay vì tạo kho khác. {1}"),
            ["vault.createdRecovery"] = ("Telegram created chat {0}. Add that existing chat to finish setup; do not create another vault for this attempt.", "Telegram đã tạo chat {0}. Thêm kho có sẵn với ID này để hoàn tất; không tạo kho khác cho lượt này."),
            ["vault.switch"] = ("Open vault", "Mở kho"),
            ["vault.attach"] = ("Add existing", "Thêm kho có sẵn"),
            ["vault.create"] = ("Create vault", "Tạo kho"),
            ["vault.attachPrompt"] = ("Enter the chat ID of an existing private TeleSelfCloud storage channel owned by this account.", "Nhập chat ID của kênh lưu trữ TeleSelfCloud riêng tư do tài khoản này sở hữu."),
            ["vault.createPrompt"] = ("Name the new vault. This creates another private Telegram channel; existing vaults are kept.", "Đặt tên kho mới. Thao tác này tạo thêm kênh Telegram riêng tư và giữ các kho hiện có."),
            ["vault.invalidId"] = ("Enter a nonzero numeric storage chat ID.", "Nhập chat ID của kho là số khác 0."),
            ["vault.opening"] = ("Verifying and opening the vault...", "Đang xác minh và mở kho..."),
            ["vault.opened"] = ("Opened {0}. Sync to import its remote catalog; other vaults and their queues were kept.", "Đã mở {0}. Đồng bộ để nhập catalog remote; giữ các kho và hàng đợi khác."),
            ["vault.isolateLegacy"] = ("Recover in a separate vault", "Phục hồi vào kho riêng"),
            ["vault.isolateLegacyTip"] = ("Create an empty vault catalog for the verified channel. The old catalog, queue, checkpoints and staged files stay in place for local recovery.", "Tạo catalog kho trống cho kênh đã xác minh. Catalog, hàng đợi, checkpoint và tệp staging cũ được giữ nguyên để phục hồi local."),
            ["vault.legacyNeedsIsolation"] = ("Some entries in the existing local catalog cannot be safely assigned to this storage chat. The catalog was kept unchanged. Use 'Recover in a separate vault' to create a clean catalog, then run a full rescan.", "Một số mục trong catalog local hiện tại không thể gán an toàn cho chat lưu trữ này. Catalog được giữ nguyên. Chọn 'Phục hồi vào kho riêng' để tạo catalog sạch, sau đó quét lại toàn bộ."),
            ["vault.legacyIsolationConfirm"] = ("Create an empty local catalog for {0}? The existing catalog with {1} local recovery item(s), queue, checkpoints and staged files will remain unchanged at its current location. Telegram history will be scanned after setup. Continue?", "Tạo catalog local trống cho {0}? Catalog hiện tại với {1} mục phục hồi local, hàng đợi, checkpoint và tệp staging sẽ được giữ nguyên tại vị trí cũ. Sau khi thiết lập, ứng dụng sẽ quét lịch sử Telegram. Tiếp tục?"),
            ["vault.legacyIsolationDone"] = ("A separate vault is ready. The old local catalog was preserved. Starting a full scan of the verified channel.", "Kho riêng đã sẵn sàng; catalog local cũ được giữ nguyên. Bắt đầu quét toàn bộ kênh đã xác minh."),
            ["vault.legacyIsolationProtected"] = ("The legacy catalog or cache has local database protection enabled. Recovery is paused so the new vault cannot silently weaken that setting. Use the local protection recovery workflow before isolating this catalog.", "Catalog hoặc cache cũ đang bật bảo vệ cơ sở dữ liệu local. Tạm dừng phục hồi để kho mới không âm thầm giảm mức bảo vệ. Hãy dùng luồng phục hồi bảo vệ local trước khi tách catalog."),
            ["vault.legacyChanged"] = ("The local catalog changed after recovery was offered. Reconnect and review its current state before continuing.", "Catalog local đã thay đổi sau khi đề xuất phục hồi. Hãy kết nối lại và kiểm tra trạng thái hiện tại trước khi tiếp tục."),
            ["vault.viewLegacy"] = ("Browse old local catalog", "Xem catalog local cũ"),
            ["vault.viewLegacyTip"] = ("Browse retained local entries and restore files with complete verified staged parts. Remote operations are unavailable in this view.", "Duyệt các mục local được giữ lại và khôi phục tệp có đủ part staging đã xác minh. Không thể thao tác remote trong chế độ này."),
            ["vault.returnFromLegacy"] = ("Return to connected vault", "Quay lại kho đang kết nối"),
            ["vault.viewLegacyOpened"] = ("Browsing the preserved local catalog. Only verified local restores are available; remote actions are disabled.", "Đang xem catalog local được giữ lại. Chỉ có thể khôi phục local đã xác minh; thao tác remote đã tắt."),
            ["sync.fullRescan"] = ("Full rescan", "Quét lại toàn bộ"),
            ["sync.fullRescanTip"] = ("Read all storage history, retaining local files, cache and recovery plans.", "Đọc toàn bộ lịch sử kho, giữ tệp local, cache và kế hoạch phục hồi."),
            ["sync.retry"] = ("Retry unfinished sync", "Thử lại đồng bộ đang dở"),
            ["sync.report.none"] = ("No saved sync attempt.", "Chưa có lượt đồng bộ đã lưu."),
            ["sync.report.running"] = ("Sync in progress...", "Đang đồng bộ..."),
            ["sync.report.interrupted"] = ("Previous sync was interrupted. Retry to verify it. Saved start: {0} pages, {1} messages, {2} indexed files.", "Lượt đồng bộ trước bị gián đoạn. Thử lại để xác minh. Đã lưu lúc bắt đầu: {0} trang, {1} tin nhắn, {2} tệp."),
            ["sync.report.completed"] = ("Sync completed: {0} pages, {1} messages, {2} indexed files.", "Đồng bộ hoàn tất: {0} trang, {1} tin nhắn, {2} tệp được lập chỉ mục."),
            ["sync.report.partial"] = ("Scan incomplete: {0} pages, {1} messages, {2} indexed files. Local entries kept; checkpoint unchanged. Retry rechecks history.", "Quét chưa hoàn tất: {0} trang, {1} tin nhắn, {2} tệp được lập chỉ mục. Giữ dữ liệu local và checkpoint cũ. Thử lại sẽ kiểm tra lại lịch sử."),
            ["sync.report.folderPending"] = ("Catalog scan completed: {0} pages, {1} messages, {2} indexed files. Checkpoint saved; retry publishes current folder structure without rescanning.", "Quét catalog hoàn tất: {0} trang, {1} tin nhắn, {2} tệp được lập chỉ mục. Đã lưu checkpoint; thử lại gửi cấu trúc thư mục hiện tại mà không quét lại."),
            ["folder.review.action"] = ("Review pending folder change", "Xem thay đổi thư mục đang dở"),
            ["folder.review.title"] = ("Pending folder change", "Thay đổi thư mục đang dở"),
            ["folder.review.files"] = ("Files in the saved folder plan", "Các tệp trong kế hoạch thư mục đã lưu"),
            ["folder.review.loading"] = ("Checking the saved folder plan...", "Đang kiểm tra kế hoạch thư mục đã lưu..."),
            ["folder.review.canceled"] = ("Folder review was canceled. The saved plan was kept.", "Đã hủy xem kế hoạch thư mục. Kế hoạch đã lưu được giữ nguyên."),
            ["folder.review.rename"] = ("{0} → {1}. Recorded steps: {2}/{3} files. New files in affected folders: {4}.", "{0} → {1}. Đã ghi nhận: {2}/{3} tệp. Tệp mới trong các thư mục liên quan: {4}."),
            ["folder.review.delete"] = ("Remove folder {0}; move its files to {1}. Recorded steps: {2}/{3} files. New affected files: {4}.", "Bỏ thư mục {0}; chuyển tệp về {1}. Đã ghi nhận: {2}/{3} tệp. Tệp mới liên quan: {4}."),
            ["folder.review.explanation"] = ("Retry continues the saved changes if files and folders still match. Stop remaining steps keeps the current local state and does not undo file moves. Changes already accepted by Telegram may appear after a later sync.", "Thử lại sẽ tiếp tục kế hoạch nếu tệp và thư mục vẫn khớp. Dừng các bước còn lại giữ trạng thái local hiện tại, không hoàn tác việc chuyển tệp. Thay đổi Telegram đã nhận vẫn có thể xuất hiện sau lần đồng bộ tiếp theo."),
            ["folder.review.state.Before"] = ("Matches the original snapshot", "Khớp bản trước thay đổi"),
            ["folder.review.state.After"] = ("Matches the applied snapshot", "Khớp bản sau thay đổi"),
            ["folder.review.state.Changed"] = ("Changed since this plan was saved", "Đã thay đổi từ khi lưu kế hoạch"),
            ["folder.review.state.Missing"] = ("Missing from the local index", "Không còn trong chỉ mục local"),
            ["folder.review.state.OtherAccount"] = ("File ID now belongs to another account; details hidden", "ID tệp hiện thuộc tài khoản khác; chi tiết được ẩn"),
            ["folder.review.location"] = ("Current folder: {0} · revision {1}", "Thư mục hiện tại: {0} · revision {1}"),
            ["folder.review.noLocalDetails"] = ("No matching local details available", "Không có chi tiết local đúng phạm vi"),
            ["folder.review.close"] = ("Close review", "Đóng phần xem kế hoạch"),
            ["folder.stop.action"] = ("Stop remaining steps", "Dừng các bước còn lại"),
            ["folder.stop.finish"] = ("Finish stopping", "Hoàn tất việc dừng"),
            ["folder.stop.pending"] = ("Stopping is saved. Retry finishes publishing the current folder structure and archiving this plan; it will not continue file moves.", "Quyết định dừng đã lưu. Thử lại sẽ hoàn tất gửi cấu trúc thư mục hiện tại và lưu trữ kế hoạch; không tiếp tục chuyển tệp."),
            ["folder.stop.confirm"] = ("Stop remaining steps for {0}? The plan recorded {1}/{2} files. Keep the current local file locations and folder structure. This does not undo changes Telegram already accepted; they may appear after a later sync. The saved plan will be archived after the current folder structure is published.", "Dừng các bước còn lại của {0}? Kế hoạch ghi nhận {1}/{2} tệp. Giữ vị trí tệp và cấu trúc thư mục local hiện tại. Không hoàn tác thay đổi Telegram đã nhận; chúng vẫn có thể xuất hiện sau lần đồng bộ tiếp theo. Kế hoạch sẽ được lưu trữ sau khi gửi cấu trúc thư mục hiện tại."),
            ["folder.stop.done"] = ("Remaining folder steps were stopped. Current local data was kept and the plan was archived.", "Đã dừng các bước thư mục còn lại. Giữ dữ liệu local hiện tại và lưu trữ kế hoạch."),
            ["folder.stop.syncPending"] = ("Stopping is saved; current data is kept. Retry to finish folder sync and archive the plan: {0}", "Đã lưu quyết định dừng; giữ dữ liệu hiện tại. Thử lại để hoàn tất đồng bộ thư mục và lưu trữ kế hoạch: {0}"),
            ["metadata.review"] = ("Review competing versions", "Xem phiên bản xung đột"),
            ["metadata.versions"] = ("Competing file organization", "Các bản tổ chức tệp xung đột"),
            ["metadata.explanation"] = ("Choose a saved version's name, folder and flags. Apply publishes a new revision while keeping the current content, parts and encryption.", "Chọn tên, thư mục và trạng thái của một bản đã lưu. Áp dụng sẽ gửi revision mới, giữ nội dung, part và mã hóa hiện tại."),
            ["metadata.current"] = ("Current: {0} · {1} · revision {2}", "Hiện tại: {0} · {1} · revision {2}"),
            ["metadata.revision"] = ("Revision {0} · updated {1}", "Revision {0} · cập nhật {1}"),
            ["metadata.root"] = ("Storage root", "Gốc kho"),
            ["metadata.unknownTime"] = ("unknown time", "chưa rõ thời điểm"),
            ["metadata.trashed"] = ("In Trash", "Trong thùng rác"),
            ["metadata.active"] = ("Outside Trash", "Ngoài thùng rác"),
            ["metadata.favorite"] = ("Favorite", "Yêu thích"),
            ["metadata.notFavorite"] = ("Not favorite", "Không yêu thích"),
            ["metadata.archived"] = ("Archived", "Đã lưu trữ"),
            ["metadata.notArchived"] = ("Not archived", "Chưa lưu trữ"),
            ["metadata.hidden"] = ("Hidden", "Ẩn"),
            ["metadata.visible"] = ("Visible", "Hiện"),
            ["metadata.apply"] = ("Apply selected organization", "Áp dụng bản tổ chức đã chọn"),
            ["metadata.prepare"] = ("Apply as a new revision", "Áp dụng bằng revision mới"),
            ["metadata.close"] = ("Close versions", "Đóng danh sách phiên bản"),
            ["metadata.empty"] = ("No competing versions are saved for this file. They are retained when sync finds organization changes at the same revision.", "Chưa có bản xung đột được lưu cho tệp này. Đồng bộ giữ lại các bản khác cách tổ chức ở cùng revision."),
            ["metadata.choose"] = ("Review the details, then apply the version you want to keep.", "Kiểm tra chi tiết rồi áp dụng bản muốn giữ."),
            ["metadata.pending"] = ("A saved selection is pending. Retry it to continue the same revision. To change your selection or include newer local metadata, apply as a new revision; the previous plan will be retained.", "Một lựa chọn đang chờ hoàn tất. Thử lại đúng bản để tiếp tục cùng revision. Để đổi lựa chọn hoặc dùng metadata local mới hơn, hãy áp dụng bằng revision mới; kế hoạch cũ sẽ được giữ lại."),
