    private static readonly IReadOnlyDictionary<string, string> ExactMessages = new Dictionary<string, string>(StringComparer.Ordinal)
    {
        ["Chat not found"] = "Chưa tìm thấy cuộc trò chuyện của kho hoặc tài khoản không còn quyền truy cập.",
        ["Connect private storage or download all file parts before opening this file."] = "Hãy kết nối kho riêng tư hoặc tải đủ các phần tệp trước khi mở tệp này.",
        ["Connect private storage or download all file parts before previewing."] = "Hãy kết nối kho riêng tư hoặc tải đủ các phần tệp trước khi xem trước.",
        ["Transfer failed. Check the connection and saved source/destination, then retry. Details were omitted for privacy."] = "Truyền tệp thất bại. Kiểm tra kết nối và nguồn/đích đã lưu rồi thử lại. Đã bỏ chi tiết để giữ riêng tư.",
        ["Local storage failed. Check free space and access to the saved source/destination, then retry. Details were omitted for privacy."] = "Lưu trữ local gặp lỗi. Kiểm tra dung lượng và quyền truy cập nguồn/đích đã lưu rồi thử lại. Đã bỏ chi tiết để giữ riêng tư.",
        ["Saved or remote data failed validation. Keep the profile and check recovery before retrying. Details were omitted for privacy."] = "Dữ liệu đã lưu hoặc remote không qua xác minh. Giữ hồ sơ và kiểm tra phục hồi trước khi thử lại. Đã bỏ chi tiết để giữ riêng tư.",
        ["A protected key or document could not be opened. Recover the correct key before retrying. Details were omitted for privacy."] = "Không mở được khóa hoặc tài liệu được bảo vệ. Phục hồi đúng khóa trước khi thử lại. Đã bỏ chi tiết để giữ riêng tư.",
        ["Access was denied. Check access to the saved source/destination and retry. Details were omitted for privacy."] = "Bị từ chối truy cập. Kiểm tra quyền với nguồn/đích đã lưu rồi thử lại. Đã bỏ chi tiết để giữ riêng tư.",
        ["Telegram rejected the operation. Check the connection, account and vault, then retry. Server details were omitted for privacy."] = "Telegram từ chối thao tác. Kiểm tra kết nối, tài khoản và kho rồi thử lại. Đã bỏ chi tiết server để giữ riêng tư.",
        ["Recover this vault's metadata key before publishing. Its protected files were kept."] = "Phục hồi khóa metadata của kho trước khi gửi. Giữ các tệp được bảo vệ.",
        ["This vault already contains protected or unsupported metadata. Recover its existing key instead of creating a new key."] = "Kho đã có metadata được bảo vệ hoặc protocol chưa hỗ trợ. Phục hồi khóa hiện có thay vì tạo khóa mới.",
        ["The vault history exceeds the key-creation scan limit. No new key was created."] = "Lịch sử kho vượt giới hạn quét trước khi tạo khóa. Chưa tạo khóa mới.",
        ["Unlock this vault with the metadata key matching its encrypted documents."] = "Phục hồi đúng khóa metadata của kho để đọc tài liệu mã hóa; sau đó thử đồng bộ lại.",
        ["The metadata key belongs to another account or vault."] = "Khóa metadata thuộc tài khoản hoặc kho khác. Hãy dùng đúng backup khóa.",
        ["The metadata key backup belongs to another account or vault."] = "Backup khóa metadata thuộc tài khoản hoặc kho khác. Hãy chọn đúng backup.",
        ["The recovery key does not match this vault's saved metadata key policy."] = "Khóa phục hồi không khớp chính sách khóa metadata đã lưu của kho. Giữ các tệp và dùng đúng backup.",
        ["This vault already has a metadata key. Recover it instead of creating a replacement."] = "Kho đã có khóa metadata. Hãy phục hồi khóa đó thay vì tạo khóa thay thế.",
        ["The local metadata key record is invalid. It was kept."] = "Bản ghi khóa metadata local không hợp lệ. Giữ tệp; hãy dùng backup để phục hồi khóa.",
        ["The metadata document exceeds the encryption size limit."] = "Metadata vượt giới hạn kích thước mã hóa. Giữ dữ liệu; hãy kiểm tra kho trước khi thử lại.",
        ["The protected metadata outbox is invalid. Its file was kept."] = "Outbox metadata mã hóa không hợp lệ. Giữ tệp; hãy sao lưu hồ sơ và kiểm tra trước khi thử lại.",
        ["The protected metadata outbox differs from its document. Both were kept."] = "Outbox metadata mã hóa khác tài liệu cần gửi. Giữ cả hai; hãy sao lưu hồ sơ và kiểm tra.",
        ["Multiple private storage vaults were found. Find vaults and choose one to open."] = "Tìm thấy nhiều kho riêng tư. Chọn Tìm kho rồi chọn kho cần mở.",
        ["The pending creation has no verified matching vault yet. Retry recovery; the creation request was not resent."] = "Chưa tìm thấy kho đã xác minh khớp lượt tạo đang dở. Hãy thử phục hồi lại; không gửi lại yêu cầu tạo kho.",
        ["More than one vault matches the pending creation. All records were kept; verify the channels before recovery."] = "Nhiều kho khớp lượt tạo đang dở. Giữ mọi bản ghi; hãy kiểm tra các kênh trước khi phục hồi.",
        ["The created vault does not match the saved creation request."] = "Kho đã tạo không khớp yêu cầu tạo đã lưu. Giữ journal để kiểm tra trước khi thử lại.",
        ["The pending vault creation is invalid. It was kept; restore a profile backup before creating another vault."] = "Journal tạo kho đang dở không hợp lệ. Giữ journal; hãy phục hồi backup hồ sơ trước khi tạo kho khác.",
        ["A vault creation is already in progress. Retry after it finishes."] = "Đang có thao tác tạo kho. Hãy thử lại khi thao tác kết thúc.",
        ["Enter a vault name of 1 to 128 characters before creating a vault."] = "Nhập tên kho từ 1 đến 128 ký tự trước khi tạo kho.",
        ["Vault discovery did not reach the end of the chat list. Retry discovery; no absence was inferred."] = "Chưa tải hết danh sách kênh. Hãy tìm kho lại; chưa kết luận kho không tồn tại.",
        ["Vault discovery returned an invalid or oversized chat list. No absence was inferred."] = "Danh sách kênh không hợp lệ hoặc vượt giới hạn. Chưa kết luận kho không tồn tại.",
        ["Vault discovery returned an invalid chat ID."] = "Danh sách kho chứa chat ID không hợp lệ. Hãy tìm kho lại.",
        ["Vault discovery received an invalid loadChats response. No absence was inferred."] = "Phản hồi tải danh sách kênh không hợp lệ. Chưa kết luận kho không tồn tại.",
        ["The active account must be the owner and a member of the storage channel."] = "Tài khoản hiện tại phải là chủ sở hữu và thành viên của kênh lưu trữ.",
        ["The vault registry is busy. Retry after the current operation."] = "Danh sách kho đang được sử dụng. Hãy thử lại sau thao tác hiện tại.",
        ["The vault registry is invalid. Existing profiles were kept; restore a registry backup before switching vaults."] = "Danh sách kho không hợp lệ. Giữ các hồ sơ hiện có; hãy phục hồi bản sao lưu danh sách kho trước khi đổi kho.",
        ["The selected vault is not registered for this account."] = "Kho đã chọn chưa được đăng ký cho tài khoản này.",
        ["The vault profile contains metadata from another account or storage chat. All local records were kept."] = "Hồ sơ kho chứa metadata của tài khoản hoặc kênh khác. Giữ toàn bộ dữ liệu local.",
        ["The migration destination contains another account or storage chat. Shared records were kept."] = "Kho đích chứa dữ liệu của tài khoản hoặc kênh khác. Dữ liệu trong workspace chung được giữ nguyên.",
        ["An existing file in the account profile differs from its shared copy. Both were kept; review the profile backup before retrying."] = "Tệp trong hồ sơ tài khoản khác với bản trong workspace chung. Cả hai được giữ nguyên; hãy sao lưu và kiểm tra hồ sơ trước khi thử lại.",
        ["The account manifest copy could not be verified; its shared source was retained."] = "Chưa xác minh được bản sao trong hồ sơ tài khoản. Bản nguồn trong workspace chung được giữ nguyên.",
        ["The account manifest copy does not retain verified staging bytes; its shared source was kept."] = "Bản sao trong hồ sơ tài khoản thiếu part local đã xác minh. Bản nguồn trong workspace chung được giữ nguyên.",
        ["The account manifest copy does not retain the verified encrypted payload; its shared source was kept."] = "Bản sao trong hồ sơ tài khoản thiếu dữ liệu mã hóa local đã xác minh. Bản nguồn trong workspace chung được giữ nguyên.",
        ["The vault name must be at most 128 characters."] = "Tên kho không được dài quá 128 ký tự.",
        ["A sync is already running for this account and vault."] = "Đang có lượt đồng bộ cho tài khoản và kho này.",
        ["The saved sync report is invalid. Full rescan can preserve it and create a new report."] = "Báo cáo đồng bộ đã lưu không hợp lệ. Quét lại toàn bộ sẽ giữ bản cũ và tạo báo cáo mới.",
        ["The sync report exceeds the safe size limit. The previous report was kept."] = "Báo cáo đồng bộ vượt giới hạn kích thước an toàn. Giữ báo cáo trước đó.",
        ["There is no pending folder publication. Sync the catalog again."] = "Không có lượt gửi cấu trúc thư mục đang dở. Hãy đồng bộ catalog lại.",
        ["The pending folder plan changed. Review it again before continuing."] = "Kế hoạch thư mục đang dở đã thay đổi. Hãy xem lại trước khi tiếp tục.",
        ["The pending folder plan changed. Review it again before stopping remaining steps."] = "Kế hoạch thư mục đang dở đã thay đổi. Hãy xem lại trước khi dừng các bước còn lại.",
        ["The stopped folder archive differs from its pending plan. Both files were kept."] = "Bản lưu trữ kế hoạch đã dừng khác với kế hoạch đang dở. Giữ cả hai tệp; hãy sao lưu hồ sơ và kiểm tra trước khi thử lại.",
        ["Metadata history is busy. Wait for the current operation and retry."] = "Lịch sử metadata đang được sử dụng. Hãy chờ thao tác hiện tại kết thúc rồi thử lại.",
        ["Metadata history exceeds the safe size limit. Its file was kept."] = "Lịch sử metadata vượt giới hạn kích thước an toàn. Tệp được giữ nguyên; hãy sao lưu hồ sơ và kiểm tra trước khi thử lại.",
        ["Metadata history is empty. Its file was kept."] = "Tệp lịch sử metadata không có dữ liệu. Tệp được giữ nguyên; hãy phục hồi từ bản sao lưu hồ sơ.",
        ["Metadata history is corrupt. Its file was kept; restore a profile backup before retrying."] = "Lịch sử metadata bị hỏng. Tệp được giữ nguyên; hãy phục hồi bản sao lưu hồ sơ trước khi thử lại.",
        ["Metadata history belongs to a different file, account, or vault. Local data was kept."] = "Lịch sử metadata thuộc tệp, tài khoản hoặc kho khác. Dữ liệu local được giữ nguyên; hãy kiểm tra phạm vi kho trước khi thử lại.",
        ["Metadata history is invalid. Its file was kept."] = "Lịch sử metadata không hợp lệ. Tệp được giữ nguyên; hãy kiểm tra hoặc phục hồi bản sao lưu hồ sơ.",
        ["Metadata resolution plan is invalid. Its file was kept."] = "Kế hoạch áp dụng metadata không hợp lệ. Tệp được giữ nguyên; hãy kiểm tra bản sao lưu hồ sơ trước khi thử lại.",
        ["No competing metadata versions were saved for this file."] = "Tệp này chưa có bản metadata xung đột đã lưu. Hãy đồng bộ kho để tìm các bản cạnh tranh.",
        ["The selected metadata version is no longer available. Refresh the versions and retry."] = "Bản metadata đã chọn không còn trong danh sách. Hãy mở lại các phiên bản rồi thử lại.",
        ["This file has an unfinished transfer. Finish or cancel it before applying a metadata version."] = "Tệp này có tác vụ truyền chưa hoàn tất. Hãy hoàn tất hoặc hủy tác vụ trước khi áp dụng phiên bản metadata.",
        ["A metadata resolution is pending. Retry the saved selection before choosing another version."] = "Một lựa chọn metadata đang chờ hoàn tất. Hãy thử lại đúng bản đã lưu trước khi chọn bản khác.",
        ["The file changed after metadata resolution started. Its plan was kept; review the new metadata before retrying."] = "Tệp đã thay đổi sau khi bắt đầu áp dụng metadata. Kế hoạch được giữ nguyên; hãy kiểm tra bản metadata mới trước khi thử lại.",
        ["Manifest revisions belong to different accounts. Local data was kept."] = "Các phiên bản metadata thuộc tài khoản khác nhau. Dữ liệu local được giữ nguyên; hãy kiểm tra tài khoản và kho trước khi đồng bộ lại.",
        ["A manifest revision changes immutable file content. Local data was kept; inspect the storage history before retrying."] = "Phiên bản metadata thay đổi kích thước hoặc hash nội dung của cùng một file. Dữ liệu local được giữ nguyên; hãy kiểm tra lịch sử kho trước khi thử lại.",
        ["Telegram recovery history is malformed. The saved transfer was kept; no new document was sent."] = "Lịch sử Telegram dùng để phục hồi không hợp lệ. Hàng đợi được giữ nguyên; chưa gửi tài liệu mới. Hãy đồng bộ và kiểm tra kho trước khi thử lại.",
        ["Telegram recovery history has invalid order, IDs, or storage scope. The saved transfer was kept; no new document was sent."] = "Lịch sử phục hồi có thứ tự, ID hoặc phạm vi kho không hợp lệ. Hàng đợi được giữ nguyên; chưa gửi tài liệu mới. Hãy kiểm tra kho trước khi thử lại.",
        ["Telegram recovery history did not advance. The saved transfer was kept; no new document was sent."] = "Lịch sử phục hồi Telegram không tiến sang trang cũ hơn. Hàng đợi được giữ nguyên; chưa gửi tài liệu mới. Hãy thử đồng bộ lại.",
        ["Telegram returned a different storage message. The saved transfer was kept."] = "Telegram trả về tin nhắn khác với tham chiếu trong kho. Hàng đợi được giữ nguyên; hãy kiểm tra dữ liệu kho trước khi thử lại.",
        ["Telegram returned a different document file. The saved transfer was kept."] = "Telegram trả về tài liệu khác với tệp được yêu cầu. Hàng đợi được giữ nguyên; hãy kiểm tra dữ liệu kho trước khi thử lại.",
        ["Telegram returned an invalid send identity. The saved transfer was kept."] = "Telegram trả về ID hoặc kho gửi không hợp lệ. Hàng đợi được giữ nguyên; hãy kiểm tra kết nối kho trước khi thử lại.",
        ["Telegram returned an invalid upload confirmation. The saved transfer was kept."] = "Xác nhận upload không khớp metadata hoặc ID hợp lệ. Hàng đợi được giữ nguyên; hãy thử tiếp tục để xác minh part đã gửi.",
        ["Invalid Telegram remote message reference."] = "Tham chiếu tin nhắn Telegram không hợp lệ. Hãy đồng bộ và kiểm tra danh mục kho trước khi thử lại.",
        ["Telegram send updates exceeded the recovery buffer. The saved transfer was kept; retry to verify the accepted document."] = "Số update gửi Telegram vượt giới hạn buffer phục hồi. Hàng đợi được giữ nguyên; hãy thử tiếp tục để xác minh tài liệu đã gửi.",
        ["A matching Telegram document is still being sent. Wait for confirmation before retrying."] = "Tài liệu khớp đang được Telegram gửi. Hãy chờ xác nhận rồi thử tiếp tục; chưa gửi bản trùng.",
        ["The Telegram storage document is not confirmed. Wait for sending to finish before retrying."] = "Tài liệu trong kho Telegram chưa được xác nhận. Hãy chờ gửi hoàn tất rồi thử lại.",
        ["Another download is using this destination. Wait for it to finish or pause it before retrying."] = "Một lượt tải hoặc khôi phục khác đang dùng đích này. Hãy chờ thao tác hoàn tất hoặc tạm dừng trước khi thử lại.",
        ["The download recovery record is invalid. Its files were kept; check the local backup before retrying."] = "Hồ sơ tiếp tục tải không hợp lệ. Các tệp được giữ nguyên; hãy kiểm tra bản sao lưu cục bộ trước khi thử lại.",
        ["A folder change is already running for this account and vault."] = "Đang có thao tác thư mục chạy cho tài khoản và kho này. Hãy chờ thao tác hoàn tất.",
        ["There is no pending folder change for this account and vault."] = "Không có thao tác thư mục cần tiếp tục cho tài khoản và kho này.",
        ["Finish the pending folder change before starting another one."] = "Hãy chọn Tiếp tục thay đổi thư mục để hoàn tất thao tác đang dang dở trước khi bắt đầu thao tác khác.",
        ["A file in the pending folder change is missing. Its recovery plan was kept."] = "Không tìm thấy một tệp trong thao tác thư mục đang dang dở. Kế hoạch phục hồi được giữ nguyên; hãy đồng bộ và kiểm tra dữ liệu kho.",
        ["A file changed while its folder operation was pending. Sync and resolve the conflict before retrying."] = "Một tệp đã thay đổi trong khi thao tác thư mục còn dang dở. Kế hoạch phục hồi được giữ nguyên; hãy đồng bộ và xử lý xung đột trước khi thử lại.",
        ["The folder contents changed while its operation was pending. Sync and resolve the conflict before retrying."] = "Nội dung thư mục đã thay đổi trong khi thao tác còn dang dở. Kế hoạch phục hồi được giữ nguyên; hãy đồng bộ và xử lý xung đột trước khi thử lại.",
        ["The folder change is incomplete. Its saved recovery plan can be resumed."] = "Thay đổi thư mục chưa hoàn tất. Chọn Tiếp tục thay đổi thư mục để chạy tiếp kế hoạch đã lưu.",
        ["Cancel and remove active transfers before changing their folder."] = "Hãy hủy và gỡ các lượt truyền đang hoạt động trước khi thay đổi thư mục chứa tệp.",
        ["The pending folder operation is corrupt; its recovery file was kept."] = "Kế hoạch thao tác thư mục bị hỏng. Tệp phục hồi được giữ nguyên; hãy kiểm tra bản sao lưu trước khi thử lại.",
        ["The pending folder operation is empty."] = "Kế hoạch thao tác thư mục bị trống. Tệp phục hồi được giữ nguyên; hãy kiểm tra bản sao lưu.",
        ["The pending folder operation exceeds the safe size limit."] = "Kế hoạch thao tác thư mục vượt giới hạn dung lượng. Hãy giảm số tệp trong thao tác; dữ liệu phục hồi hiện có được giữ nguyên.",
        ["The pending folder operation is invalid; its recovery file was kept."] = "Kế hoạch thao tác thư mục không hợp lệ. Tệp phục hồi được giữ nguyên; hãy kiểm tra bản sao lưu.",
        ["The pending folder operation has an invalid checkpoint."] = "Điểm tiếp tục của thao tác thư mục không hợp lệ. Hãy kiểm tra bản sao lưu; tệp phục hồi được giữ nguyên.",
        ["The pending folder operation has a missing file plan."] = "Kế hoạch thao tác thư mục thiếu thông tin tệp. Hãy kiểm tra bản sao lưu; tệp phục hồi được giữ nguyên.",
        ["The pending folder operation has an inconsistent file plan."] = "Thông tin tệp trong kế hoạch thao tác thư mục không nhất quán. Hãy kiểm tra bản sao lưu; tệp phục hồi được giữ nguyên.",
        ["The pending folder operation changes file data outside its folder."] = "Kế hoạch thao tác thư mục chứa thay đổi dữ liệu tệp ngoài phạm vi cho phép. Đã dừng; tệp phục hồi được giữ nguyên.",
        ["The pending folder operation has an inconsistent folder plan."] = "Thông tin thư mục trong kế hoạch thao tác không nhất quán. Hãy kiểm tra bản sao lưu; tệp phục hồi được giữ nguyên.",
        ["A catalog sync is already running."] = "Đang có lượt đồng bộ danh mục. Hãy chờ lượt này kết thúc.",
        ["Telegram history replayed messages newer than the requested cursor; the sync checkpoint was not advanced."] = "Telegram trả về lịch sử phân trang không nhất quán. Điểm đồng bộ được giữ nguyên; hãy thử đồng bộ lại.",
        ["Telegram history returned a message from a different storage channel; the sync checkpoint was not advanced."] = "Lịch sử chứa mục thuộc kho khác. Đã dừng đồng bộ và giữ nguyên điểm tiếp tục; hãy kiểm tra kho đang kết nối.",
        ["A remote catalog caption is malformed; the sync checkpoint was not advanced."] = "Thông tin nhận diện danh mục trên Telegram bị lỗi. Điểm đồng bộ được giữ nguyên; hãy kiểm tra dữ liệu kho trước khi thử lại.",
        ["The remote manifest schema version is not supported; the sync checkpoint was not advanced."] = "Kho chứa định dạng danh mục chưa được hỗ trợ. Điểm đồng bộ được giữ nguyên; hãy kiểm tra bản cập nhật ứng dụng.",
        ["A remote manifest part points outside the active storage channel."] = "Danh mục tham chiếu tới phần tệp ngoài kho đang kết nối. Đã dừng đồng bộ; hãy kiểm tra dữ liệu kho.",
        ["Remote folder state contains a null folder entry."] = "Danh mục thư mục trên Telegram có mục bị thiếu dữ liệu. Đã dừng đồng bộ; hãy kiểm tra dữ liệu kho.",
        ["Remote folder state contains a null tombstone."] = "Danh mục thư mục trên Telegram có bản ghi xóa bị thiếu dữ liệu. Đã dừng đồng bộ; hãy kiểm tra dữ liệu kho.",
        ["Manifest contains a null part entry."] = "Danh mục tệp có phần bị thiếu dữ liệu. Hãy kiểm tra danh mục hoặc khôi phục từ bản sao hợp lệ.",
        ["Ready. Files and manifests remain on this Windows profile."] = "Sẵn sàng. Tệp và danh mục được lưu trong hồ sơ Windows này.",
        ["Log in and connect storage before starting queued transfers."] = "Hãy đăng nhập và kết nối kho trước khi chạy hàng đợi truyền tệp.",
