    public static UiText Instance { get; } = new();
    private string _language = "vi";

    public event PropertyChangedEventHandler? PropertyChanged;
    public event EventHandler? LanguageChanged;

    public string this[string key] => Get(key);
    public string Language => _language;

    public string Get(string key)
    {
        if (!Strings.TryGetValue(key, out var value)) return key;
        return _language == "vi" ? value.Vietnamese : value.English;
    }

    public void LoadPreference(string path)
    {
        try
        {
            if (!File.Exists(path)) return;
            var saved = JsonSerializer.Deserialize<LanguagePreference>(File.ReadAllText(path));
            _language = saved?.Language == "en" ? "en" : "vi";
        }
        catch
        {
            _language = "vi";
        }
    }

    public void SetLanguage(string language, string path)
    {
        var normalized = language == "en" ? "en" : "vi";
        if (_language == normalized) return;
        _language = normalized;
        try
        {
            Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);
            File.WriteAllText(path, JsonSerializer.Serialize(new LanguagePreference(normalized)));
        }
        catch { /* Keep the selected language for this session if local settings are read-only. */ }
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs("Item[]"));
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(Language)));
        LanguageChanged?.Invoke(this, EventArgs.Empty);
    }

    public string LocalizeMessage(string english)
    {
        if (_language == "en") return english;
        var createdVaultFailure = CreatedVaultFailurePattern.Match(english);
        if (createdVaultFailure.Success)
            return string.Format(CultureInfo.CurrentCulture, Get("vault.verificationRecovery"), createdVaultFailure.Groups[1].Value,
                LocalizeMessage(createdVaultFailure.Groups[2].Value));
        Match accountStatus = AccountStatusPattern.Match(english);
        if (accountStatus.Success)
        {
            string plan = Get(accountStatus.Groups[2].Value == "Premium" ? "account.premium" : "account.standard");
            return string.Format(CultureInfo.CurrentCulture, Get("auth.accountStatus"), accountStatus.Groups[1].Value, plan, accountStatus.Groups[3].Value);
        }
        Match scanStatus = SyncStatusPattern.Match(english);
        if (scanStatus.Success)
        {
            string kind = Get(scanStatus.Groups[1].Value == "Incremental" ? "sync.incremental" : "sync.full");
            string state = Get(scanStatus.Groups[2].Value == "in progress" ? "sync.state.progress" : "sync.state.completed");
            return string.Format(CultureInfo.CurrentCulture, Get("status.syncScanProgress"), kind, state,
                scanStatus.Groups[3].Value, scanStatus.Groups[4].Value, scanStatus.Groups[5].Value, scanStatus.Groups[6].Value);
        }
        const string sendingPrefix = "Sending a ";
        const string sendingSuffix = "-byte Telegram document...";
        if (english.StartsWith(sendingPrefix, StringComparison.Ordinal) && english.EndsWith(sendingSuffix, StringComparison.Ordinal))
        {
            string bytes = english[sendingPrefix.Length..^sendingSuffix.Length];
            return string.Format(CultureInfo.CurrentCulture, Get("status.sendingDocument"), bytes);
        }
        if (ExactMessages.TryGetValue(english, out var exact)) return exact;
        foreach (var (source, translated) in PrefixMessages)
            if (english.StartsWith(source, StringComparison.Ordinal))
                return translated + english[source.Length..];
        return english;
    }

    private sealed record LanguagePreference(string Language);
}

[MarkupExtensionReturnType(typeof(object))]
public sealed class UiTextExtension : MarkupExtension
{
    public string Key { get; set; } = string.Empty;

    public override object ProvideValue(IServiceProvider serviceProvider) =>
        new Binding($"[{Key}]") { Source = UiText.Instance, Mode = BindingMode.OneWay }.ProvideValue(serviceProvider);
}

public sealed class LocalizedTextBlock : System.Windows.Controls.TextBlock
{
    private string? _sourceText;
    private bool _settingTranslatedValue;
    private bool _listening;

    static LocalizedTextBlock() => TextProperty.OverrideMetadata(typeof(LocalizedTextBlock),
        new System.Windows.FrameworkPropertyMetadata(string.Empty, TextValueChanged));

    public LocalizedTextBlock()
    {
        Loaded += (_, _) =>
        {
            if (!_listening) { UiText.Instance.LanguageChanged += LanguageChanged; _listening = true; }
            ApplyTranslation();
        };
        Unloaded += (_, _) =>
        {
            if (_listening) { UiText.Instance.LanguageChanged -= LanguageChanged; _listening = false; }
        };
    }

    private static void TextValueChanged(System.Windows.DependencyObject sender, System.Windows.DependencyPropertyChangedEventArgs e)
    {
        var control = (LocalizedTextBlock)sender;
        if (control._settingTranslatedValue) return;
        control._sourceText = control.Text;
        control.ApplyTranslation();
    }

    private void LanguageChanged(object? sender, EventArgs e)
    {
        if (Dispatcher.HasShutdownStarted || Dispatcher.HasShutdownFinished) return;
        if (Dispatcher.CheckAccess()) ApplyTranslation();
        else Dispatcher.BeginInvoke((Action)(() => { if (_listening) ApplyTranslation(); }));
    }

    private void ApplyTranslation()
    {
        if (_sourceText is null) return;
        var translated = UiText.Instance.LocalizeMessage(_sourceText);
        if (translated == Text) return;
        _settingTranslatedValue = true;
        try { SetCurrentValue(TextProperty, translated); }
        finally { _settingTranslatedValue = false; }
    }
}



